<?php $kioskFeatureEnabled=!empty($kiosk_feature_enabled);$kioskLink=!empty($clinic_uuid)?base_url('kiosk/'.$clinic_uuid.'/check-in'):'';$kioskEnabled=!empty($settings['kiosk_enabled']);$kioskReady=$kioskFeatureEnabled&&$kioskEnabled&&!empty($kiosk_pin_set); ?>
<section class="form-section"><header><h2><?= esc(lang('UI.settingsKioskAccessSecurity')) ?></h2><p><?= esc(lang('UI.settingsKioskAccessSecurityHelp')) ?></p></header><?php if(!$kioskFeatureEnabled): ?><p class="settings-warning"><?= esc(lang('UI.settingsKioskDisabledByPlan')) ?></p><?php endif; ?><form method="post" action="<?= base_url('settings/updateKiosk') ?>" data-settings-form><?= csrf_field() ?><label class="settings-switch"><span><?= esc(lang('UI.settingsEnableKioskCheckin')) ?></span><input type="checkbox" name="kiosk_enabled" value="1" <?= $kioskEnabled?'checked':'' ?> <?= $kioskFeatureEnabled&&$settingsEdit?'':'disabled' ?>></label><div class="settings-pin-fields"><?php foreach(['kiosk_pin'=>'TenantMisc.newPin','kiosk_pin_confirm'=>'TenantMisc.confirmPin'] as $name=>$key): ?><div class="form-field"><label for="setting-<?= $name ?>"><?= esc(lang($key)) ?></label><input type="password" inputmode="numeric" name="<?= $name ?>" id="setting-<?= $name ?>" autocomplete="new-password" dir="ltr" <?= $kioskFeatureEnabled&&$settingsEdit?'':'disabled' ?>></div><?php endforeach; ?></div><p class="settings-help"><?= esc(lang('TenantMisc.kioskPinHelp')) ?></p><footer class="settings-save"><button class="button primary" type="submit" <?= $kioskFeatureEnabled&&$settingsEdit?'':'disabled' ?>><?= esc(lang('UI.settingsSaveKioskSettings')) ?></button></footer></form></section>
<section class="form-section"><header><h2><?= esc(lang('UI.settingsKioskLaunchShare')) ?></h2></header><div class="settings-kiosk-share"><div><div class="form-field"><label for="kioskLinkInput"><?= esc(lang('UI.settingsKioskLink')) ?></label><input id="kioskLinkInput" readonly value="<?= esc($kioskLink,'attr') ?>" dir="ltr"></div><div class="settings-actions"><button class="button secondary" type="button" data-copy-kiosk <?= $kioskFeatureEnabled?'':'disabled' ?>><?= esc(lang('UI.settingsCopyLink')) ?></button><a class="button secondary" href="<?= esc($kioskLink,'attr') ?>" target="_blank" rel="noopener" <?= $kioskFeatureEnabled?'':'aria-disabled="true" tabindex="-1"' ?>><?= esc(lang('UI.settingsOpenLink')) ?></a><button class="button secondary" type="button" data-download-kiosk disabled><?= esc(lang('UI.settingsDownloadQr')) ?></button></div><p class="settings-feedback" data-kiosk-feedback role="status"></p><dl class="settings-summary"><div><dt><?= esc(lang('UI.settingsEnableKioskCheckin')) ?></dt><dd><?= esc(lang($kioskEnabled?'UI.settingsKioskEnabledState':'UI.settingsKioskDisabledState')) ?></dd></div><div><dt><?= esc(lang('UI.settingsKioskPinLabel')) ?></dt><dd><?= esc(lang(!empty($kiosk_pin_set)?'UI.settingsPinSet':'UI.settingsPinNotSet')) ?></dd></div><div><dt><?= esc(lang('TenantMisc.defaultLanguage')) ?></dt><dd><?= esc(lang('TenantMisc.arabicDefault')) ?></dd></div></dl></div><div class="settings-kiosk-qr"><div id="kioskQrCode" data-ready="<?= $kioskReady?'1':'0' ?>"></div><p id="kioskQrStatus" role="status" data-ready="<?= esc(lang('UI.settingsKioskQrReady'),'attr') ?>" data-failed="<?= esc(lang('UI.settingsKioskQrFailed'),'attr') ?>"><?= esc(lang($kioskReady?'UI.settingsKioskQrReady':'UI.settingsKioskQrUnavailable')) ?></p></div></div></section>
